// Emit one output item per PDF attachment.
// - Skips items with no binary data.
// - Skips non-PDF binaries.
// - Preserves pairedItem so downstream nodes can still use $().item.
// - Canonicalises the binary key to 'data'.

const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];
  if (!item.binary) continue;

  for (const key of Object.keys(item.binary)) {
    const b = item.binary[key];
    if (!b || b.mimeType !== 'application/pdf') continue;

    out.push({
      json: { ...item.json, _sourceFileName: b.fileName || key },
      binary: { data: { ...b } },
      pairedItem: { item: i }
    });
  }
}

return out;

// Parse Claude's JSON response into structured fields.
// Tolerant of code fences and surrounding prose. On failure, emits a
// record with _parseFailed=true so the final task is still created and
// flagged for Arin.

const item = $input.first();
const raw = item.json && item.json.text ? item.json.text : '';
const sourceFileName = item.json && item.json._sourceFileName;

const blank = {
  business_name: null,
  description: null,
  website: null,
  instagram: null,
  contact_name: null,
  contact_role: null,
  contact_email: null,
  contact_phone: null,
  location_city: null,
  location_country: null,
  business_type: null,
  pricing_details: [],
  contract_type: null
};

let parsed = null;
let parseFailed = false;

try {
  const match = String(raw).match(/\{[\s\S]*\}/);
  if (!match) throw new Error('No JSON object found in Claude response');
  parsed = JSON.parse(match[0]);
} catch (e) {
  parseFailed = true;
  parsed = {};
}

return [{
  json: {
    ...blank,
    ...parsed,
    _sourceFileName: sourceFileName || null,
    _parseFailed: parseFailed,
    _rawClaudeText: parseFailed ? raw : undefined
  }
}];

// Normalize website URL: add https:// if missing, null out empties.
const items = $input.all();
return items.map(item => {
  const json = { ...item.json };
  let w = json.website;
  if (typeof w === 'string') w = w.trim();
  if (!w) {
    json.website = null;
  } else if (!/^https?:\/\//i.test(w)) {
    json.website = 'https://' + w;
  } else {
    json.website = w;
  }
  return { json };
});

// Pull the first instagram.com result out of SerpAPI's response and
// attach it to the original business profile as `instagram`.
// The original profile fields were carried through on $json (SerpAPI
// HTTP node returns body at top level; original fields remain on
// paired item — we re-read them via $('Normalize Website URL').item).

const profile = $('Normalize Website URL').item.json;
const body = $json || {};
const results = Array.isArray(body.organic_results) ? body.organic_results : [];

let igUrl = null;
for (const r of results) {
  const link = r && r.link;
  if (typeof link === 'string' && /^https?:\/\/(www\.)?instagram\.com\//i.test(link)) {
    igUrl = link.split('?')[0];
    break;
  }
}

return [{
  json: {
    ...profile,
    instagram: igUrl || profile.instagram || null
  }
}];

// Merge both branches of Has Website? and decide which URL to fetch.
// Preference: website first, then instagram, else null.

const items = $input.all();
return items.map(item => {
  const json = { ...item.json };
  const resolved = json.website || json.instagram || null;
  json._resolvedUrl = resolved;
  return { json };
});

// Crawl Website (sitemap-aware)
//
// Captures “full website” rather than just the homepage:
//   1. Fetches /sitemap.xml from the resolved URL's origin.
//   2. If it's a sitemap index (all entries are other .xml files),
//      flattens up to 2 sub-sitemaps.
//   3. Picks the homepage + up to 5 internal pages whose path matches
//      facility/amenity/class/service/about/pricing keywords.
//   4. Falls back to the single resolved URL if sitemap is missing,
//      a login wall (Instagram), or any other failure.
//   5. Fetches all pages with a real UA + short timeout, swallowing
//      per-page errors so one dead page doesn't kill the rest.
//   6. Strips <script>, <style>, comments, tags, entities; normalises
//      whitespace; concatenates; truncates at 40,000 chars.
//
// Emits a single item per input: profile + _pageText + _fetchEmpty
// + _pagesFetched/_pagesAttempted for debugging.

const helpers = this.helpers;
const profile = $input.first().json;
const baseUrl = profile._resolvedUrl;

const UA = 'Mozilla/5.0 (compatible; BODDY-Intake/1.0; +https://boddy.tech)';
const TIMEOUT = 15000;
const KEYWORDS = /\/(facilit|amenit|class|service|about|member|pricing|studio|experience|offering|wellness|fitness|train)/i;
const MAX_PAGES = 6;
const MAX_CHARS = 40000;

const emptyOut = () => [{ json: { ...profile, _pageText: '', _fetchEmpty: true, _pagesFetched: 0, _pagesAttempted: 0 } }];

if (!baseUrl) return emptyOut();

const fetchText = async (url) => {
  try {
    const res = await helpers.httpRequest({
      url,
      method: 'GET',
      timeout: TIMEOUT,
      returnFullResponse: false,
      headers: {
        'User-Agent': UA,
        'Accept': 'text/html,application/xhtml+xml,application/xml'
      }
    });
    return typeof res === 'string' ? res : (res ? String(res) : '');
  } catch (e) {
    return '';
  }
};

const stripHtml = (html) => String(html || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&amp;|&quot;|&#39;|&lt;|&gt;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Discover candidate URLs from sitemap.xml
let pages = [baseUrl];
let origin = null;
try { origin = new URL(baseUrl).origin; } catch (e) { /* malformed url */ }

if (origin && !/instagram\.com$/i.test(new URL(baseUrl).hostname)) {
  const sitemapText = await fetchText(origin + '/sitemap.xml');
  if (sitemapText) {
    let locs = Array.from(sitemapText.matchAll(/<loc>([^<]+)<\/loc>/gi)).map(m => m[1].trim());

    // Sitemap index: all entries are other .xml files
    const allXml = locs.length > 0 && locs.every(u => /\.xml(\?|$)/i.test(u));
    if (allXml) {
      const flattened = [];
      for (const sm of locs.slice(0, 2)) {
        const sub = await fetchText(sm);
        flattened.push(...Array.from(sub.matchAll(/<loc>([^<]+)<\/loc>/gi)).map(m => m[1].trim()));
      }
      locs = flattened;
    }

    const relevant = locs
      .filter(u => KEYWORDS.test(u) && u !== baseUrl)
      .slice(0, MAX_PAGES - 1);
    pages = [baseUrl, ...relevant];
  }
}

// Fetch all selected pages
const texts = [];
for (const url of pages) {
  const html = await fetchText(url);
  const stripped = stripHtml(html);
  if (stripped) texts.push(stripped);
}

let combined = texts.join('\n\n').trim();
if (combined.length > MAX_CHARS) combined = combined.slice(0, MAX_CHARS);

return [{
  json: {
    ...profile,
    _pageText: combined,
    _fetchEmpty: !combined,
    _pagesFetched: texts.length,
    _pagesAttempted: pages.length
  }
}];

// Parse Classify node response; extract description (always required),
// facilities, and amenities. Merge with PDF-extracted profile from
// Crawl Website. Description always has a value: website-derived first,
// then PDF-extraction fallback.

const profile = $('Crawl Website').item.json;
const current = $json || {};

let raw = '';
if (Array.isArray(current.content)) {
  const textBlock = current.content.find(c => c && c.type === 'text');
  if (textBlock && typeof textBlock.text === 'string') raw = textBlock.text;
} else if (typeof current.text === 'string') {
  raw = current.text;
}

// Bug fix: initialise with description field and actually read it from parsed.
let classified = { description: '', facilities: [], amenities: [] };
try {
  const m = String(raw).match(/\{[\s\S]*\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    if (typeof parsed.description === 'string') classified.description = parsed.description.trim();
    if (Array.isArray(parsed.facilities)) classified.facilities = parsed.facilities;
    if (Array.isArray(parsed.amenities)) classified.amenities = parsed.amenities;
  }
} catch (e) { /* swallow — falls back to profile.description */ }

// Website-based description first, then PDF-extracted, then empty string.
const finalDescription = classified.description || profile.description || '';

// Only flag for manual review when extraction completely failed or we have
// no URL at all and still no description to show.
const needsReview = Boolean(
  profile._parseFailed ||
  (!profile.website && !profile.instagram && !classified.description)
);

const fmt = v => (v === null || v === undefined || v === '') ? '\u2014' : v;
const fmtList = a => (Array.isArray(a) && a.length) ? a.map(x => '- ' + x).join('\n') : '\u2014';

const reasons = [
  profile._parseFailed && 'PDF extraction failed',
  (!profile.website && !profile.instagram && !classified.description) && 'no URL found and no description generated'
].filter(Boolean);

const reviewBanner = needsReview
  ? '> **Needs review** \u2014 arin.melvin@boddy.tech\n> Reasons: ' + reasons.join('; ') + '\n\n'
  : '';

const body = reviewBanner
  + '## About\n' + fmt(finalDescription)
  + '\n\n## Contact\n- Name: ' + fmt(profile.contact_name)
  + '\n- Role: ' + fmt(profile.contact_role)
  + '\n- Email: ' + fmt(profile.contact_email)
  + '\n- Phone: ' + fmt(profile.contact_phone)
  + '\n\n## Location\n' + fmt(profile.location_city) + ', ' + fmt(profile.location_country)
  + '\n\n## Business\n- Type: ' + fmt(profile.business_type)
  + '\n- Website: ' + fmt(profile.website)
  + '\n- Instagram: ' + fmt(profile.instagram)
  + '\n\n## Facilities\n' + fmtList(classified.facilities)
  + '\n\n## Amenities\n' + fmtList(classified.amenities)
  + '\n\n## Pricing\n' + fmtList(profile.pricing_details)
  + '\n\n## Contract\n' + fmt(profile.contract_type)
  + '\n\n---\nSource file: ' + fmt(profile._sourceFileName);

const name = (needsReview ? '[REVIEW \u2014 Arin] ' : '') + (profile.business_name || 'New Partner');

return [{
  json: {
    task_name: name,
    task_content: body,
    needs_review: needsReview,
    facilities: classified.facilities,
    amenities: classified.amenities,
    ...profile
  }
}];
